BEGIN
 IF current_database()<>'postgres' OR current_user<>'postgres' OR session_user<>'postgres' OR current_setting('server_version_num')::integer/10000<>17 OR current_setting('server_encoding')<>'UTF8' THEN RAISE EXCEPTION 'CTBC executor identity/version mismatch'; END IF;
 IF current_setting('lock_timeout')<>'5s' OR current_setting('statement_timeout')<>'30s' OR current_setting('transaction_timeout')<>'90s' THEN RAISE EXCEPTION 'CTBC timeout mismatch'; END IF;
 -- Controller supplied READ ONLY catalog/body evidence. Compare every reviewed
 -- field, not an invented aggregate hash. Native executor still unverified.
 IF event_review_receipt IS DISTINCT FROM '__LOCAL_EVENT_RECEIPT__' OR event_reviewed_exact_ddl IS NOT TRUE THEN RAISE EXCEPTION 'CTBC event-trigger review UNKNOWN STOP'; END IF;
 IF current_setting('session_replication_role')<>'origin' OR (WITH expected(trigger_name,event,enabled,tags,owner,function_signature,function_body_sha256,function_owner,security_definer) AS (VALUES
__LOCAL_EVENT_ROWS__
), actual AS (SELECT e.evtname::text AS trigger_name,e.evtevent::text AS event,e.evtenabled::text AS enabled,e.evttags AS tags,pg_get_userbyid(e.evtowner)::text AS owner,e.evtfoid::regprocedure::text AS function_signature,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS function_body_sha256,pg_get_userbyid(p.proowner)::text AS function_owner,p.prosecdef AS security_definer FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid WHERE e.evtenabled<>'D' ORDER BY e.evtname) SELECT count(*) FROM expected e FULL JOIN actual a USING(trigger_name) WHERE e.trigger_name IS NULL OR a.trigger_name IS NULL OR ROW(e.event,e.enabled,e.tags,e.owner,e.function_signature,e.function_body_sha256,e.function_owner,e.security_definer) IS DISTINCT FROM ROW(a.event,a.enabled,a.tags,a.owner,a.function_signature,a.function_body_sha256,a.function_owner,a.security_definer))<>0 THEN RAISE EXCEPTION 'CTBC event-trigger fingerprint drift STOP'; END IF;
 IF (SELECT count(*) FROM pg_attribute WHERE attrelid=to_regclass('supabase_migrations.schema_migrations') AND NOT attisdropped AND attname IN ('version','name','statements'))<>3 THEN RAISE EXCEPTION 'CTBC history not provisioned'; END IF;
 IF NOT (SELECT rolcreaterole FROM pg_roles WHERE rolname=current_user) THEN RAISE EXCEPTION 'CTBC executor cannot create exact NOLOGIN roles'; END IF;
 IF NOT has_schema_privilege(current_user,'public','USAGE') OR NOT has_schema_privilege(current_user,'public','CREATE') OR NOT has_schema_privilege(current_user,'supabase_migrations','USAGE') OR NOT has_table_privilege(current_user,'supabase_migrations.schema_migrations','INSERT') OR NOT has_schema_privilege(current_user,'auth','USAGE') OR NOT has_function_privilege(current_user,'auth.uid()','EXECUTE') THEN RAISE EXCEPTION 'CTBC required privilege missing'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'ctbc_%') OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'ctbc_%') OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN ('ctbc_executor','ctbc_link_locker')) THEN RAISE EXCEPTION 'CTBC existing objects/roles STOP'; END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='supabase_migrations.schema_migrations'::regclass AND NOT tgisinternal) THEN RAISE EXCEPTION 'CTBC history trigger STOP'; END IF;
 IF (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid='public.transactions'::regclass)<>'postgres' OR (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid='supabase_migrations.schema_migrations'::regclass)<>'postgres' THEN RAISE EXCEPTION 'CTBC object owner drift'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_index i ON i.indexrelid=c.conindid WHERE c.conrelid='public.transactions'::regclass AND c.conname='transactions_user_source_source_id_key' AND c.contype='u' AND c.convalidated AND i.indisvalid AND i.indisready AND i.indisunique AND pg_get_constraintdef(c.oid)='UNIQUE (user_id, source, source_id)') THEN RAISE EXCEPTION 'CTBC S8 prerequisite drift'; END IF;
 IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='public.transactions'::regclass AND conname='transactions_source_check') IS DISTINCT FROM 'CHECK ((source = ANY (ARRAY[''legacy''::text, ''manual''::text, ''ynab_import''::text, ''hermes''::text])))' THEN RAISE EXCEPTION 'CTBC source constraint baseline drift STOP'; END IF;
 LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;
 IF (WITH expected(version,name,count_text,sha) AS (VALUES
__LOCAL_HISTORY_ROWS__
) SELECT count(*) FROM expected e FULL JOIN supabase_migrations.schema_migrations h USING(version) WHERE e.version IS NULL OR h.version IS NULL OR h.name IS DISTINCT FROM e.name OR cardinality(h.statements)::text IS DISTINCT FROM e.count_text OR encode(sha256(convert_to(array_to_json(h.statements)::text,'UTF8')),'hex') IS DISTINCT FROM e.sha)<>0 THEN RAISE EXCEPTION 'CTBC pre-existing version/hash/history drift STOP'; END IF;
 SELECT count(*) INTO ledger_before FROM public.transactions;
 IF octet_length(raw_0)<>31840 OR encode(sha256(raw_0),'hex')<>'0700d8fe87f9bb8612ca2e8b7afec676ba5772bd8ace631a6ecfe2dd9be3f89b' OR cardinality(history_0)<>61 OR encode(sha256(convert_to(array_to_json(history_0)::text,'UTF8')),'hex')<>'0584d15315624587e72073f13ef347e29e9596edccab1b62c01ebe4014251ec7' THEN RAISE EXCEPTION 'CTBC 20261008002233 byte/history seal mismatch'; END IF;
 EXECUTE convert_from(raw_0,'UTF8');
 INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20261008002233','ctbc_inbox',history_0);
IF octet_length(raw_1)<>11929 OR encode(sha256(raw_1),'hex')<>'619dcda59d4fed2f06dd3f82f9c698bdff1d54b91551ab893a1effb190935bf6' OR cardinality(history_1)<>22 OR encode(sha256(convert_to(array_to_json(history_1)::text,'UTF8')),'hex')<>'cb4dd1f2f0285e5a252d3dc1f591fd390ee28590a9971d87d74f3fafb0f2fccc' THEN RAISE EXCEPTION 'CTBC 20261008013654 byte/history seal mismatch'; END IF;
 EXECUTE convert_from(raw_1,'UTF8');
 INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20261008013654','ctbc_worker_lifecycle',history_1);
 IF (WITH expected(version,name,count_text,sha) AS (VALUES
__LOCAL_HISTORY_ROWS__,
('20261008002233','ctbc_inbox','61','0584d15315624587e72073f13ef347e29e9596edccab1b62c01ebe4014251ec7'),
('20261008013654','ctbc_worker_lifecycle','22','cb4dd1f2f0285e5a252d3dc1f591fd390ee28590a9971d87d74f3fafb0f2fccc')
) SELECT count(*) FROM expected e FULL JOIN supabase_migrations.schema_migrations h USING(version) WHERE e.version IS NULL OR h.version IS NULL OR h.name IS DISTINCT FROM e.name OR cardinality(h.statements)::text IS DISTINCT FROM e.count_text OR encode(sha256(convert_to(array_to_json(h.statements)::text,'UTF8')),'hex') IS DISTINCT FROM e.sha)<>0 THEN RAISE EXCEPTION 'CTBC post history mismatch'; END IF;
 IF (SELECT count(*) FROM public.transactions)<>ledger_before THEN RAISE EXCEPTION 'CTBC concurrent ledger count drift STOP'; END IF;
 IF EXISTS(SELECT 1 FROM public.ctbc_collector_scopes) OR EXISTS(SELECT 1 FROM public.ctbc_batches) OR EXISTS(SELECT 1 FROM public.ctbc_candidates) OR EXISTS(SELECT 1 FROM public.ctbc_events) OR EXISTS(SELECT 1 FROM public.ctbc_worker_cursors) OR EXISTS(SELECT 1 FROM public.ctbc_worker_attempts) THEN RAISE EXCEPTION 'CTBC unexpected seed/state STOP'; END IF;
 IF (WITH expected(role_name) AS (VALUES ('ctbc_executor'),('ctbc_link_locker')), actual AS (SELECT r.rolname AS role_name,a.member AS member_oid,m.rolname AS member_name,a.grantor AS grantor_oid,g.rolname AS grantor_name,g.rolsuper AS grantor_superuser,a.admin_option,a.inherit_option,a.set_option FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.roleid JOIN pg_roles m ON m.oid=a.member JOIN pg_roles g ON g.oid=a.grantor WHERE r.rolname IN ('ctbc_executor','ctbc_link_locker')) SELECT count(*) FROM expected e FULL JOIN actual a USING(role_name) WHERE e.role_name IS NULL OR a.role_name IS NULL OR a.member_name IS DISTINCT FROM 'postgres' OR a.member_oid IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname='postgres') OR a.grantor_oid IS DISTINCT FROM 10::oid OR a.grantor_name IS DISTINCT FROM 'supabase_admin' OR a.grantor_superuser IS DISTINCT FROM true OR a.admin_option IS DISTINCT FROM true OR a.inherit_option IS DISTINCT FROM false OR a.set_option IS DISTINCT FROM false)<>0 THEN RAISE EXCEPTION 'CTBC bootstrap ADMIN-only membership drift STOP'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN ('ctbc_executor','ctbc_link_locker') AND (rolcanlogin OR rolinherit OR rolbypassrls OR rolsuper OR rolcreaterole OR rolcreatedb OR has_schema_privilege(rolname,'public','CREATE'))) THEN RAISE EXCEPTION 'CTBC role privilege drift'; END IF;
 IF EXISTS(SELECT 1 FROM (WITH expected(name,body_sha,owner_name,security_definer,browser_allowed,service_allowed) AS (VALUES
('ctbc_request_owner','34ae01224735e7d8ff5ab5c0a9fc18c6aeea7f6d4cb88807894c8eb06ec12b2e','postgres',true,false,false),
('ctbc_lock_references','f8aab40658ad9238d74e2f5ad40b9dff7000c2756daf11195886bfcc6f824d61','ctbc_link_locker',true,false,false),
('ctbc_recheck_risk','d07ebdfb5c180cfceff80fcc97b4ac9a479667e4314fa910c22c1520aa7339c8','ctbc_executor',true,false,false),
('ctbc_act','38ac40772a520204eaa8770a862dbac89bf1dd682696cbd92eb9ca507e485126','ctbc_executor',true,true,false),
('ctbc_batch_preflight','57211df8b7935e330eb7321b0c6569882e18700935a78b9ba1aff6ee85fde2f7','ctbc_executor',true,true,false),
('ctbc_retain','cbeb86fb96f5abcf64486a91f647abddca67ee0529a6e8ed9c984c2df19fb546','postgres',false,false,true),
('ctbc_begin','356a7a1efbfe1d4a1d125898c8ccde4bdda4bf50add54f49a21f8a21f9bcea13','postgres',false,false,true),
('ctbc_ingest','daa6d0d980f73c78d5b6d3b70b39ee275b6931354d5513d9c5635ab3d17dda4e','postgres',false,false,true),
('ctbc_snapshot','7e48d991098ad96643e6837ce316f10baf81acfd4b3760b5f33ad779f20168db','ctbc_executor',true,true,false),
('ctbc_worker_binding','a657df30a58e1e5e53ced306692d5abe1f097426a70f556872354c42a8e91af4','postgres',false,false,true),
('ctbc_worker_probe','986f1a431ccb6464b4d8020349882562edc336339c472451c2025a6e82ef5e3d','postgres',false,false,true),
('ctbc_worker_finish','ced3b55778ce4cef24ac92244b3f4f05dcfb59d34030be6f0794b97fa6a53ca2','postgres',false,false,true),
('ctbc_worker_commit','3fbc4ef40eadb0c7162a94f6307a2c23c0040c80a985ef7a346bcbba38d94687','postgres',false,false,true),
('ctbc_worker_poll','9724550a760ab442bff530d996b19ec236ae2ae710edc5aa8e80edfc25a223a0','postgres',false,false,true)
) SELECT e.*,p.oid::regprocedure::text AS signature,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS actual_body_sha,pg_get_userbyid(p.proowner) AS actual_owner,p.prosecdef,p.proconfig,has_function_privilege((SELECT oid FROM pg_roles WHERE rolname='anon'),p.oid,'EXECUTE') AS anon_execute,has_function_privilege((SELECT oid FROM pg_roles WHERE rolname='authenticated'),p.oid,'EXECUTE') AS authenticated_execute,has_function_privilege((SELECT oid FROM pg_roles WHERE rolname='service_role'),p.oid,'EXECUTE') AS service_execute FROM expected e LEFT JOIN pg_proc p ON p.proname=e.name AND p.pronamespace='public'::regnamespace ORDER BY e.name) q WHERE signature IS NULL OR actual_body_sha<>body_sha OR actual_owner<>owner_name OR prosecdef<>security_definer OR anon_execute OR authenticated_execute<>browser_allowed OR (service_allowed AND NOT service_execute)) THEN RAISE EXCEPTION 'CTBC function body/owner/execute drift'; END IF;
END;
$ctbc_release_guarded$;
